def validate_topics(name, raw_topics):
    print(f"Validating {len(raw_topics)} {name} topics...")
    assert len(raw_topics) == 100, f"Expected 100 topics for {name}, got {len(raw_topics)}"
    seen_titles = set()
    for i, t in enumerate(raw_topics):
        title, subj, syst, focus, ref_label, ref_url = t
        assert title not in seen_titles, f"Duplicate title in {name} at index {i}: {title}"
        seen_titles.add(title)
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} in {name} topic {title}"
        assert syst in TAXONOMY_SYSTEMS, f"Invalid system {syst} in {name} topic {title}"
        assert len(focus) > 20, f"Focus too short in {name} topic {title}"
        assert len(ref_label) > 5, f"Ref label too short in {name} topic {title}"
        assert ref_url.startswith("https://"), f"Ref url must start with https:// in {name} topic {title}"
    print(f"Validated {len(raw_topics)} {name} topics successfully.")

if __name__ == "__main__":
    validate_topics("HAAD", HAAD_RAW)
    validate_topics("PLAB", PLAB_RAW)

    with open("scripts/mega57_topics_a.py", "w", encoding="utf-8") as f:
        f.write('"""Generated Mega-Batch 57 Part A Topics"""\n\n')
        f.write(f"HAAD_TOPICS = {repr(HAAD_RAW)}\n\n")
        f.write(f"PLAB_TOPICS = {repr(PLAB_RAW)}\n")

    print("Wrote scripts/mega57_topics_a.py successfully.")
